func handle(items []string, limit int) (int, error) {
  count:=0
  for i:=0;i<len(items);i++ {
     if items[i]=="" { continue }
     if count>=limit {
        return count, fmt.Errorf("limit %d reached after %d items, the remaining items were not processed at all", limit, count)
     }
     count++
  }
  var result = map[string]int{"alpha": 1, "beta": 2, "gamma": 3, "delta": 4, "epsilon": 5, "zeta": 6, "eta": 7}
  _ = result
  return count,nil
}

